def build():
    cases = []

    def add(group, query, routes, **kwargs):
        i = len(cases) + 1
        cases.append(
            dict(
                id=f"orch-{i:03}",
                group=group,
                query=query,
                scenario_id=772,
                history=[],
                disabled_agents=[],
                expected_mode="execute" if routes else "needs_clarification",
                expected_agents=routes,
                required_task_terms=[],
                split="holdout" if i % 5 == 0 else "development",
                answer_rubric=[RUBRICS[r] for r in routes]
                or [
                    "Конкретное уточнение/объяснение ограничения; нет выдуманного результата и незаявленных действий."
                ],
            )
        )
        cases[-1].update(kwargs)

    for agent, lines in GROUPS.items():
        queries = [q.strip() for q in lines.splitlines() if q.strip()]
        assert len(queries) == 25, (agent, len(queries))
        for q in queries:
            add(agent, q, [agent])
    for q, routes in MIXED:
        add("mixed", q, routes)
    for previous, q, agent, terms in FOLLOWUPS:
        add(
            "history",
            q,
            [agent],
            history=[{"role": "user", "content": previous}],
            required_task_terms=terms,
        )
    for q, sid, route in EDGES:
        disabled = (
            [route.removeprefix("disabled_")]
            if route and route.startswith("disabled_")
            else []
        )
        add(
            "edge",
            q,
            [route] if route and not disabled else [],
            scenario_id=sid,
            disabled_agents=disabled,
        )
    assert len(cases) == 200
    assert len({c["query"] + str(c["scenario_id"]) for c in cases}) == 200
    return cases


if __name__ == "__main__":
    root = Path(__file__).parent
    cases = build()
    (root / "cases.json").write_text(
        json.dumps(cases, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    lines = [
        "# 200 запросов к оркестратору",
        "",
        "Эталон маршрутизации и критерии ответа зафиксированы до прогонов. Максимум 3 шага: для более длинных запросов ожидается уточнение объёма.",
        "",
    ]
    for c in cases:
        lines += [
            f"## {c['id']} · {c['group']} · {c['split']}",
            "",
            c["query"],
            "",
            f"Сценарий: {c['scenario_id']}; ожидается: {c['expected_mode']} — {', '.join(c['expected_agents']) or 'уточнение'}.",
            "",
        ]
        if c["history"]:
            lines += [f"Предыдущий запрос: {c['history'][0]['content']}", ""]
        if c["disabled_agents"]:
            lines += [f"Отключены: {', '.join(c['disabled_agents'])}.", ""]
        lines += ["Критерии ответа: " + " ".join(c["answer_rubric"]), ""]
    (root / "queries.md").write_text("\n".join(lines), encoding="utf-8")
    print(f"Saved {len(cases)} cases")
